    # Condition 3: GCD of any three distinct elements is 1
    for triplet in combinations(U, 3):
        if gcd_list(list(triplet)) != 1:
            return False

    # Condition 4: For any two distinct elements x, y, there exists z such that z | xy
    U_list = list(U)
    N = len(U_list)
    for i in range(N):
        for j in range(i + 1, N):
            x = U_list[i]
            y = U_list[j]
            product = x * y

            found_divisor = False
            # Iterate over all other elements z in U
            for k in range(N):
                if k != i and k != j:
                    z = U_list[k]
                    if product % z == 0:
                        found_divisor = True
                        break

            if not found_divisor:
                return False

    return True

def get_factors(n):
    # Returns all divisors > 1
    divs = set()
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    divs.add(n)
    return sorted(list(divs))

def is_good_number(m):
    if m < 24: # Minimum possible product for |U|=3 with distinct elements > 1
        return False

    divisors = get_factors(m)

    # We use a recursive approach to find all distinct sets U whose product is m
    # Current product starts at 1, current set U starts empty.

    def find_factorizations(remaining_product, start_index, current_set):
        if remaining_product == 1:
            if len(current_set) >= 3:
                if is_good_set(current_set):
                    return True
            return False

        # Optimization: if remaining product is prime and smaller than smallest element in U,
        # it cannot be included unless U already has enough factors.

        for i in range(start_index, len(divisors)):
            d = divisors[i]
            if remaining_product % d == 0:
                new_product = remaining_product // d

                # To ensure we only generate distinct factorizations (e.g., {2, 3, 4} but not {3, 2, 4})
                # we only proceed if d is >= the last element added (which is guaranteed by start_index)

                # Recurse
                if find_factorizations(new_product, i + 1, current_set + [d]):
                    return True
        return False

    # Start search. We only need to find ONE good set U for m to be a good number.
    return find_factorizations(m, 0, [])

